window.TERMS = [{"id":"c01-chemical","chapter":1,"section":"1.1","term":"chemical","short":"chemical","clue":"Any substance with a fixed makeup and identical properties no matter where it is sampled."},
{"id":"c01-chemistry","chapter":1,"section":"1.1","term":"chemistry","short":"chemistry","clue":"The science of what matter is made of, how it is built, how it behaves, and how it transforms."},
{"id":"c01-conclusion","chapter":1,"section":"1.2","term":"conclusion","short":"conclusion","clue":"The final judgment on a hypothesis, reached once many repeated tests back it up."},
{"id":"c01-experiment","chapter":1,"section":"1.2","term":"experiment","short":"experiment","clue":"A controlled test designed to check whether a proposed explanation holds up."},
{"id":"c01-hypothesis","chapter":1,"section":"1.2","term":"hypothesis","short":"hypothesis","clue":"A tentative, testable explanation proposed for something seen in nature."},
{"id":"c01-observation","chapter":1,"section":"1.2","term":"observation","short":"observation","clue":"Facts gathered by carefully watching, measuring, and recording what happens in nature."},
{"id":"c01-scientific-method","chapter":1,"section":"1.2","term":"scientific method","short":"sci. method","clue":"Observe, propose an explanation, test it again and again, then draw a conclusion."},
{"id":"c01-scientific-notation","chapter":1,"section":"1.5","term":"scientific notation","short":"sci. notation","clue":"Writing a number as a coefficient from 1 up to (not including) 10 times a power of ten."},
{"id":"c02-celsius-scale","chapter":2,"section":"2.1","term":"Celsius scale (°C)","short":"Celsius (°C)","clue":"Temperature scale that puts water's freezing point at 0 degrees and its boiling point at 100."},
{"id":"c02-centimeter","chapter":2,"section":"2.1","term":"centimeter (cm)","short":"centimeter","clue":"One-hundredth of a meter; exactly 2.54 of them make one inch."},
{"id":"c02-conversion-factor","chapter":2,"section":"2.5","term":"conversion factor","short":"conv. factor","clue":"A ratio built from an equality, such as 2.54 cm/1 in, used to switch a quantity to new units."},
{"id":"c02-cubic-centimeter","chapter":2,"section":"2.4","term":"cubic centimeter (cm³)","short":"cm³","clue":"Volume of a cube one-hundredth of a meter on each edge; exactly equal to 1 mL."},
{"id":"c02-density","chapter":2,"section":"2.7","term":"density","short":"density","clue":"How much mass is packed into each unit of volume; mass divided by volume, e.g., g/mL."},
{"id":"c02-equality","chapter":2,"section":"2.4","term":"equality","short":"equality","clue":"Two different units set equal because they describe the same amount, like 1 ft = 12 in."},
{"id":"c02-exact-number","chapter":2,"section":"2.2","term":"exact number","short":"exact number","clue":"A value with no uncertainty because it comes from counting or a definition, like 12 in a dozen."},
{"id":"c02-gram","chapter":2,"section":"2.1","term":"gram (g)","short":"gram","clue":"Basic metric unit of mass; a paper clip has a mass of about one."},
{"id":"c02-international-system","chapter":2,"section":"2.1","term":"International System (SI)","short":"SI units","clue":"Modern, globally adopted version of the metric system, with base units such as kg, m, s, and K."},
{"id":"c02-kelvin-scale","chapter":2,"section":"2.1","term":"Kelvin scale (K)","short":"Kelvin (K)","clue":"Temperature scale that starts at absolute zero, the coldest possible point, so it has no negative values."},
{"id":"c02-kilogram","chapter":2,"section":"2.1","term":"kilogram (kg)","short":"kilogram","clue":"SI base unit of mass, equal to 1000 grams or about 2.2 pounds."},
{"id":"c02-liter","chapter":2,"section":"2.1","term":"liter (L)","short":"liter","clue":"Metric volume unit a bit bigger than a quart; equal to one cubic decimeter."},
{"id":"c02-mass","chapter":2,"section":"2.1","term":"mass","short":"mass","clue":"How much matter an object contains, measured in grams or kilograms."},
{"id":"c02-measured-number","chapter":2,"section":"2.2","term":"measured number","short":"measured no.","clue":"A value read from a tool such as a ruler or balance, always carrying some uncertainty."},
{"id":"c02-meter","chapter":2,"section":"2.1","term":"meter (m)","short":"meter","clue":"SI base unit of length, a little longer than a yard."},
{"id":"c02-metric-system","chapter":2,"section":"2.1","term":"metric system","short":"metric system","clue":"Decimal-based measuring system used in science and by nearly every nation."},
{"id":"c02-milliliter","chapter":2,"section":"2.1","term":"milliliter (mL)","short":"milliliter","clue":"A thousand of these make one liter; it is the same volume as 1 cm³."},
{"id":"c02-prefix","chapter":2,"section":"2.4","term":"prefix","short":"prefix","clue":"The front part of a unit name, like kilo- or milli-, that scales it by a power of ten."},
{"id":"c02-second","chapter":2,"section":"2.1","term":"second (s)","short":"second","clue":"Base unit of time in both SI and metric systems; 60 of them make a minute."},
{"id":"c02-significant-figures","chapter":2,"section":"2.2","term":"significant figures (SFs)","short":"sig figs","clue":"All the certain digits in a measurement plus the one final estimated digit."},
{"id":"c02-specific-gravity","chapter":2,"section":"2.7","term":"specific gravity (sp gr)","short":"specific gravity","clue":"A sample's density divided by the density of water; a unitless comparison."},
{"id":"c02-temperature","chapter":2,"section":"2.1","term":"temperature","short":"temperature","clue":"A gauge of how hot or cold something is, read in °C, °F, or K."},
{"id":"c02-volume","chapter":2,"section":"2.1","term":"volume (V)","short":"volume","clue":"The amount of three-dimensional space a sample takes up."},
{"id":"c03-calorie","chapter":3,"section":"3.4","term":"calorie (cal)","short":"calorie","clue":"Energy that heats one gram of water by one degree Celsius; equal to 4.184 J."},
{"id":"c03-chemical-change","chapter":3,"section":"3.2","term":"chemical change","short":"chem. change","clue":"A process that turns substances into new ones with a different makeup, like iron rusting."},
{"id":"c03-chemical-properties","chapter":3,"section":"3.2","term":"chemical properties","short":"chem. property","clue":"Traits describing how a substance can react to form something new, like flammability."},
{"id":"c03-compound","chapter":3,"section":"3.1","term":"compound","short":"compound","clue":"Pure substance with at least two elements bonded in a fixed ratio; only reactions can split it."},
{"id":"c03-element","chapter":3,"section":"3.1","term":"element","short":"element","clue":"Pure substance made of only one kind of atom; no reaction can break it into anything simpler."},
{"id":"c03-energy","chapter":3,"section":"3.4","term":"energy","short":"energy","clue":"The capacity to do work or cause change."},
{"id":"c03-energy-value","chapter":3,"section":"3.6","term":"energy value","short":"energy value","clue":"Kilocalories or kilojoules released per gram of carbohydrate, fat, or protein in food."},
{"id":"c03-gas","chapter":3,"section":"3.1","term":"gas","short":"gas","clue":"State of matter with no fixed shape or volume; it spreads out to fill any container."},
{"id":"c03-heat","chapter":3,"section":"3.2","term":"heat","short":"heat","clue":"Energy tied to particle motion that flows from a warmer object to a cooler one."},
{"id":"c03-heat-equation","chapter":3,"section":"3.5","term":"heat equation","short":"heat equation","clue":"q = m × ΔT × SH: computes the energy a sample gains or loses as its temperature changes."},
{"id":"c03-joule","chapter":3,"section":"3.4","term":"joule (J)","short":"joule","clue":"SI unit of energy; 4.184 of them equal one calorie."},
{"id":"c03-kinetic-energy","chapter":3,"section":"3.4","term":"kinetic energy","short":"kinetic energy","clue":"The kind of energy carried by anything in motion; the faster it moves, the more it has."},
{"id":"c03-liquid","chapter":3,"section":"3.1","term":"liquid","short":"liquid","clue":"State of matter with a fixed volume that flows to take its container's shape."},
{"id":"c03-matter","chapter":3,"section":"3.1","term":"matter","short":"matter","clue":"Anything that has mass and takes up space."},
{"id":"c03-mixture","chapter":3,"section":"3.1","term":"mixture","short":"mixture","clue":"Two or more substances combined physically, not bonded, so they can be separated again."},
{"id":"c03-physical-change","chapter":3,"section":"3.2","term":"physical change","short":"phys. change","clue":"A change in form or state, such as melting, that leaves the substance's identity intact."},
{"id":"c03-physical-properties","chapter":3,"section":"3.2","term":"physical properties","short":"phys. property","clue":"Traits like color or melting point you can measure without changing what the substance is."},
{"id":"c03-potential-energy","chapter":3,"section":"3.4","term":"potential energy","short":"potential energy","clue":"Stored energy due to an object's position or a substance's chemical makeup."},
{"id":"c03-pure-substance","chapter":3,"section":"3.1","term":"pure substance","short":"pure substance","clue":"Matter with a fixed, uniform composition: either an element or a compound."},
{"id":"c03-solid","chapter":3,"section":"3.1","term":"solid","short":"solid","clue":"State of matter that keeps its own definite shape and volume."},
{"id":"c03-specific-heat","chapter":3,"section":"3.5","term":"specific heat (SH)","short":"specific heat","clue":"Energy needed to warm one gram of a material by one degree Celsius; water's value is unusually high."},
{"id":"c03-states-of-matter","chapter":3,"section":"3.2","term":"states of matter","short":"states of matter","clue":"Solid, liquid, and gas: the three common physical forms a substance can take."},
{"id":"c04-alkali-metal","chapter":4,"section":"4.2","term":"alkali metal","short":"alkali metal","clue":"Soft, highly reactive Group 1A (1) element like Na or K, with one valence electron; H excluded."},
{"id":"c04-alkaline-earth-metal","chapter":4,"section":"4.2","term":"alkaline earth metal","short":"alk. earth metal","clue":"Group 2A (2) element such as Mg or Ca, with two valence electrons; reactive, but less so than Group 1A."},
{"id":"c04-atom","chapter":4,"section":"4.3","term":"atom","short":"atom","clue":"The tiniest unit that still counts as a given element, made of a nucleus and electrons."},
{"id":"c04-atomic-mass","chapter":4,"section":"4.3","term":"atomic mass","short":"atomic mass","clue":"Average of an element's natural isotope masses, weighted by abundance; listed in amu."},
{"id":"c04-atomic-mass-unit","chapter":4,"section":"4.3","term":"atomic mass unit (amu)","short":"amu","clue":"Tiny mass unit defined as 1/12 the mass of a carbon-12 atom; roughly one proton's mass."},
{"id":"c04-atomic-number","chapter":4,"section":"4.4","term":"atomic number","short":"atomic number","clue":"How many protons an atom's nucleus holds; it identifies the element."},
{"id":"c04-atomic-symbol","chapter":4,"section":"4.5","term":"atomic symbol","short":"atomic symbol","clue":"Isotope notation such as ¹²₆C, with the mass number on top and the proton count below."},
{"id":"c04-chemical-symbol","chapter":4,"section":"4.1","term":"chemical symbol","short":"chem. symbol","clue":"One- or two-letter abbreviation for an element's name, like Fe for iron."},
{"id":"c04-electron","chapter":4,"section":"4.3","term":"electron","short":"electron","clue":"Negatively charged particle with almost no mass, found outside the nucleus."},
{"id":"c04-group","chapter":4,"section":"4.2","term":"group","short":"group","clue":"A vertical column of the periodic table; its members behave alike chemically."},
{"id":"c04-group-number","chapter":4,"section":"4.2","term":"group number","short":"group number","clue":"Label atop a periodic-table column; for A columns it gives the number of outer-shell electrons."},
{"id":"c04-halogen","chapter":4,"section":"4.2","term":"halogen","short":"halogen","clue":"Group 7A (17) element like F, Cl, Br, or I, with seven outer-shell electrons."},
{"id":"c04-isotope","chapter":4,"section":"4.5","term":"isotope","short":"isotope","clue":"Atoms of one element with equal proton counts but unequal neutron counts, so their masses differ."},
{"id":"c04-mass-number","chapter":4,"section":"4.4","term":"mass number","short":"mass number","clue":"Protons plus neutrons in an atom's nucleus."},
{"id":"c04-metal","chapter":4,"section":"4.2","term":"metal","short":"metal","clue":"Shiny, malleable element that conducts heat and electricity well; found left of the zigzag line."},
{"id":"c04-metalloid","chapter":4,"section":"4.2","term":"metalloid","short":"metalloid","clue":"Element on the staircase line with in-between traits, like silicon or boron."},
{"id":"c04-neutron","chapter":4,"section":"4.3","term":"neutron","short":"neutron","clue":"Uncharged particle of about 1 amu located in the nucleus."},
{"id":"c04-noble-gas","chapter":4,"section":"4.2","term":"noble gas","short":"noble gas","clue":"Group 8A (18) element like neon or argon: very unreactive, with a full outer shell."},
{"id":"c04-nonmetal","chapter":4,"section":"4.2","term":"nonmetal","short":"nonmetal","clue":"Dull, brittle element that conducts heat and electricity poorly; found right of the zigzag line."},
{"id":"c04-nucleus","chapter":4,"section":"4.3","term":"nucleus","short":"nucleus","clue":"Tiny, dense core of an atom holding its protons and neutrons."},
{"id":"c04-period","chapter":4,"section":"4.2","term":"period","short":"period","clue":"A horizontal row of the element chart, such as the one running from Li to Ne."},
{"id":"c04-periodic-table","chapter":4,"section":"4.2","term":"periodic table","short":"periodic table","clue":"Chart of elements in order of atomic number, arranged so columns share similar behavior."},
{"id":"c04-proton","chapter":4,"section":"4.3","term":"proton","short":"proton","clue":"Positively charged particle of about 1 amu in the nucleus; its count defines the element."},
{"id":"c04-representative-element","chapter":4,"section":"4.2","term":"representative element","short":"rep. element","clue":"Main-group member of columns 1A–8A (1, 2, 13–18), on the far left and right of the table."},
{"id":"c04-subatomic-particle","chapter":4,"section":"4.3","term":"subatomic particle","short":"subatomic part.","clue":"Any of the tiny pieces that make up an atom: protons, neutrons, or electrons."},
{"id":"c04-transition-element","chapter":4,"section":"4.2","term":"transition element","short":"transition elem","clue":"Metal from the table's central block, labeled B or numbered 3–12, like Fe or Cu."},
{"id":"c05-atomic-size","chapter":5,"section":"5.6","term":"atomic size","short":"atomic size","clue":"How far an atom's outermost electrons sit from its nucleus; it shrinks going across a period."},
{"id":"c05-atomic-spectrum","chapter":5,"section":"5.2","term":"atomic spectrum","short":"atomic spectrum","clue":"Unique pattern of bright colored lines an element gives off as its excited electrons drop back down."},
{"id":"c05-orbital-diagram","chapter":5,"section":"5.4","term":"orbital diagram","short":"orbital diagram","clue":"Sketch of boxes with up and down arrows showing how an atom's electrons and their spins are placed."},
{"id":"c05-d-block","chapter":5,"section":"5.1","term":"d block","short":"d block","clue":"Middle section of the table (Groups 3–12, transition metals) where the last electrons enter a set of five orbitals."},
{"id":"c05-p-block","chapter":5,"section":"5.1","term":"p block","short":"p block","clue":"Groups 13–18 on the right side of the table, where the last electrons go into a set of three orbitals."},
{"id":"c05-em-radiation","chapter":5,"section":"5.1","term":"electromagnetic radiation","short":"EM radiation","clue":"Energy carried by oscillating electric and magnetic fields; light, radio, and X-rays are all examples."},
{"id":"c05-photon","chapter":5,"section":"5.2","term":"photon","short":"photon","clue":"Smallest bundle of light energy; the shorter its wavelength, the more energy it carries."},
{"id":"c05-principal-qn","chapter":5,"section":"5.2","term":"principal quantum number (n)","short":"principal n","clue":"Whole number 1, 2, 3… naming an electron's main shell; larger values lie farther from the nucleus."},
{"id":"c05-em-spectrum","chapter":5,"section":"5.1","term":"electromagnetic spectrum","short":"EM spectrum","clue":"Full range of radiant energy laid out by wavelength, from long radio waves to short gamma rays."},
{"id":"c05-electron-config","chapter":5,"section":"5.4","term":"electron configuration","short":"electron config","clue":"Shorthand such as 1s² 2s² 2p⁶ telling how many electrons occupy each sublevel of an atom."},
{"id":"c05-s-block","chapter":5,"section":"5.1","term":"s block","short":"s block","clue":"Groups 1 and 2 plus helium, where the outermost electron goes into a single spherical orbital."},
{"id":"c05-energy-level","chapter":5,"section":"5.2","term":"energy level","short":"energy level","clue":"Main shell around the nucleus, labeled n = 1, 2, 3…, whose electrons sit at a similar distance and energy."},
{"id":"c05-sublevel","chapter":5,"section":"5.3","term":"sublevel","short":"sublevel","clue":"Part of a main shell labeled s, p, d, or f; all of its orbitals have the same energy."},
{"id":"c05-f-block","chapter":5,"section":"5.1","term":"f block","short":"f block","clue":"Two rows parked below the main table, the lanthanides and actinides, where seven-orbital sets fill."},
{"id":"c05-frequency","chapter":5,"section":"5.1","term":"frequency","short":"frequency","clue":"Count of wave cycles going by a fixed spot each second, reported in hertz (Hz)."},
{"id":"c05-valence-electrons","chapter":5,"section":"5.6","term":"valence electrons","short":"valence e⁻","clue":"Electrons in an atom's outermost shell; they are the ones that take part in bonding."},
{"id":"c05-ionization-energy","chapter":5,"section":"5.6","term":"ionization energy","short":"ionization E","clue":"Energy it takes to pull the most loosely held electron away from an atom in the gas phase."},
{"id":"c05-wavelength","chapter":5,"section":"5.1","term":"wavelength","short":"wavelength","clue":"Distance from one wave crest to the next, often given in nanometers for light."},
{"id":"c05-metallic-character","chapter":5,"section":"5.6","term":"metallic character","short":"metallic char.","clue":"How readily an atom gives up its outer electrons; it increases going down a group and to the left."},
{"id":"c05-orbital","chapter":5,"section":"5.3","term":"orbital","short":"orbital","clue":"3D region where an electron is likely to be found; each holds at most two electrons (s ones are spheres)."},
{"id":"c06-anion","chapter":6,"section":"6.1","term":"anion","short":"anion","clue":"Negatively charged particle formed when an atom gains electrons, such as Cl⁻ or O²⁻."},
{"id":"c06-cation","chapter":6,"section":"6.1","term":"cation","short":"cation","clue":"Positively charged particle formed when an atom loses electrons, such as Na⁺ or Ca²⁺."},
{"id":"c06-chemical-formula","chapter":6,"section":"6.2","term":"chemical formula","short":"chem. formula","clue":"Element symbols with subscripts, like H₂O, telling which atoms make up a compound and in what numbers."},
{"id":"c06-covalent-bond","chapter":6,"section":"6.1","term":"covalent bond","short":"covalent bond","clue":"Link formed when two atoms, usually nonmetals, share one or more pairs of electrons."},
{"id":"c06-ion","chapter":6,"section":"6.1","term":"ion","short":"ion","clue":"Charged particle made when an atom, or a bonded group of atoms, picks up or gives away electrons."},
{"id":"c06-ionic-bond","chapter":6,"section":"6.1","term":"ionic bond","short":"ionic bond","clue":"Electrostatic pull holding oppositely charged particles together after a metal hands electrons to a nonmetal."},
{"id":"c06-ionic-charge","chapter":6,"section":"6.1","term":"ionic charge","short":"ionic charge","clue":"Superscript such as 2+ or 3− on a symbol; equals protons minus electrons for a charged atom."},
{"id":"c06-ionic-compound","chapter":6,"section":"6.1","term":"ionic compound","short":"ionic compound","clue":"Substance like NaCl built from positive and negative particles packed in a repeating lattice."},
{"id":"c06-molecular-compound","chapter":6,"section":"6.1","term":"molecular compound","short":"molecular cmpd","clue":"Substance like H₂O or CO₂ whose nonmetal atoms are joined by shared electrons rather than transfer."},
{"id":"c06-molecule","chapter":6,"section":"6.5","term":"molecule","short":"molecule","clue":"Smallest separate particle of a substance, built from atoms linked by shared electron pairs, like H₂O."},
{"id":"c06-octet-rule","chapter":6,"section":"6.1","term":"octet rule","short":"octet rule","clue":"Main-group atoms tend to gain, lose, or share electrons until their outer shell holds eight."},
{"id":"c06-polyatomic-ion","chapter":6,"section":"6.4","term":"polyatomic ion","short":"polyatomic ion","clue":"Charged cluster of bonded atoms, like SO₄²⁻ or NH₄⁺, that stays together as one unit."},
{"id":"c07-avogadros-number","chapter":7,"section":"7.1","term":"Avogadro’s number","short":"Avogadro’s no.","clue":"The value 6.022 × 10²³, which is how many particles make up one mole."},
{"id":"c07-empirical-formula","chapter":7,"section":"7.5","term":"empirical formula","short":"empirical form.","clue":"Lowest whole-number ratio of atoms in a compound; CH₂O for glucose, for example."},
{"id":"c07-mass-percent","chapter":7,"section":"7.4","term":"mass percent composition","short":"mass % comp.","clue":"Share of a compound's total mass contributed by each element, expressed in percent."},
{"id":"c07-molar-mass","chapter":7,"section":"7.2","term":"molar mass","short":"molar mass","clue":"Grams in one mole of a substance; found by adding up the atomic masses in its formula."},
{"id":"c07-mole","chapter":7,"section":"7.1","term":"mole","short":"mole","clue":"SI counting unit for amount of substance, a chemist's 'dozen' for atoms and other tiny particles."},
{"id":"c07-molecular-formula","chapter":7,"section":"7.5","term":"molecular formula","short":"molecular form.","clue":"Shows exactly how many atoms of each element one molecule holds, like C₆H₁₂O₆ for glucose."},
{"id":"c08-balanced-equation","chapter":8,"section":"8.1","term":"balanced equation","short":"balanced eqn","clue":"Reaction written with equal counts of every kind of atom on both sides of the arrow."},
{"id":"c08-chemical-equation","chapter":8,"section":"8.1","term":"chemical equation","short":"chem. equation","clue":"Written recipe of a reaction: formulas of starting materials, an arrow, then formulas of what forms."},
{"id":"c08-coefficients","chapter":8,"section":"8.1","term":"coefficients","short":"coefficients","clue":"Leading numbers, such as the 2 in 2H₂O, used to make atom counts match on both sides."},
{"id":"c08-combination-rxn","chapter":8,"section":"8.3","term":"combination reaction","short":"combination rxn","clue":"Two or more substances join to make one product: A + B → AB."},
{"id":"c08-combustion-rxn","chapter":8,"section":"8.3","term":"combustion reaction","short":"combustion rxn","clue":"A carbon-containing fuel burns in O₂, releasing CO₂, H₂O, and heat."},
{"id":"c08-decomposition-rxn","chapter":8,"section":"8.3","term":"decomposition reaction","short":"decomposition","clue":"One compound breaks down into smaller compounds or elements: AB → A + B."},
{"id":"c08-double-replacement","chapter":8,"section":"8.3","term":"double replacement reaction","short":"double replace.","clue":"Two compounds swap partners, their cations trading places: AB + CD → AD + CB."},
{"id":"c08-oxidation","chapter":8,"section":"8.4","term":"oxidation","short":"oxidation","clue":"Giving up electrons so the charge goes up; in biology, often gaining O or losing H."},
{"id":"c08-redox-rxn","chapter":8,"section":"8.4","term":"oxidation–reduction reaction","short":"redox reaction","clue":"Electron-transfer reaction in which one substance loses electrons while another gains them."},
{"id":"c08-products","chapter":8,"section":"8.1","term":"products","short":"products","clue":"Substances written to the right of the arrow; what a reaction makes."},
{"id":"c08-reactants","chapter":8,"section":"8.1","term":"reactants","short":"reactants","clue":"Starting materials written left of the arrow; they get used up as the change occurs."},
{"id":"c08-reduction","chapter":8,"section":"8.4","term":"reduction","short":"reduction","clue":"Gaining electrons so the charge goes down; in biology, often losing O or gaining H."},
{"id":"c08-single-replacement","chapter":8,"section":"8.3","term":"single replacement reaction","short":"single replace.","clue":"One element bumps another out of its compound: A + BC → AC + B."},
{"id":"c09-actual-yield","chapter":9,"section":"9.5","term":"actual yield","short":"actual yield","clue":"Amount of product you really collect when a reaction is carried out in the lab."},
{"id":"c09-endothermic","chapter":9,"section":"9.6","term":"endothermic reaction","short":"endothermic","clue":"Reaction that soaks up heat, so products hold more energy than reactants; ΔH > 0."},
{"id":"c09-exothermic","chapter":9,"section":"9.6","term":"exothermic reaction","short":"exothermic","clue":"Reaction that gives off heat, so products end up lower in energy; ΔH < 0."},
{"id":"c09-heat-of-reaction","chapter":9,"section":"9.6","term":"heat of reaction","short":"heat of reaction","clue":"ΔH, the enthalpy change taken in or given off during a reaction run at fixed pressure."},
{"id":"c09-hess-law","chapter":9,"section":"9.6","term":"Hess’s law","short":"Hess’s law","clue":"Total ΔH is the same whether a reaction happens in one step or several; just add the steps' ΔH values."},
{"id":"c09-conservation-of-mass","chapter":9,"section":"9.1","term":"Law of Conservation of Mass","short":"conserv. of mass","clue":"Matter is neither created nor destroyed in a reaction, so mass before equals mass after."},
{"id":"c09-limiting-reactant","chapter":9,"section":"9.4","term":"limiting reactant","short":"limiting react.","clue":"Ingredient that runs out first, capping how much product can form."},
{"id":"c09-mole-mole-factor","chapter":9,"section":"9.2","term":"mole–mole factor","short":"mole–mole factor","clue":"Ratio taken from equation coefficients, like 2 mol H₂ / 1 mol O₂, linking two substances."},
{"id":"c09-percent-yield","chapter":9,"section":"9.5","term":"percent yield","short":"percent yield","clue":"(Actual ÷ theoretical) × 100%; how close a reaction came to its maximum possible product."},
{"id":"c09-theoretical-yield","chapter":9,"section":"9.5","term":"theoretical yield","short":"theor. yield","clue":"Most product that could form from the given starting amounts if everything went perfectly."},
{"id":"c10-bent","chapter":10,"section":"10.3","term":"bent","short":"bent","clue":"V-shaped geometry: a central atom bonded to two others and carrying one or two lone pairs, like H₂O."},
{"id":"c10-boiling","chapter":10,"section":"10.6","term":"boiling","short":"boiling","clue":"Vapor bubbles forming all through the body of a liquid, not just at its surface."},
{"id":"c10-boiling-point","chapter":10,"section":"10.6","term":"boiling point (bp)","short":"boiling point","clue":"The temperature where a liquid vaporizes throughout; vapor condenses back at this same point."},
{"id":"c10-change-of-state","chapter":10,"section":"10.7","term":"change of state","short":"change of state","clue":"Shift of matter from one physical form to another, such as solid to liquid or liquid to gas."},
{"id":"c10-condensation","chapter":10,"section":"10.7","term":"condensation","short":"condensation","clue":"Gas turning into liquid, like dew forming on cool grass overnight."},
{"id":"c10-cooling-curve","chapter":10,"section":"10.7","term":"cooling curve","short":"cooling curve","clue":"Graph of temperature as heat is taken away, with flat plateaus wherever the substance changes phase."},
{"id":"c10-deposition","chapter":10,"section":"10.7","term":"deposition","short":"deposition","clue":"Gas turning straight into solid with no liquid stage, like frost forming on a window."},
{"id":"c10-dipole","chapter":10,"section":"10.4","term":"dipole","short":"dipole","clue":"Split of partial + and − charge across a bond, drawn as an arrow toward the more electronegative atom."},
{"id":"c10-dipole-dipole","chapter":10,"section":"10.6","term":"dipole–dipole attractions","short":"dipole–dipole","clue":"Pull between the slightly + end of one polar molecule and the slightly − end of a neighbor."},
{"id":"c10-dispersion","chapter":10,"section":"10.6","term":"dispersion forces","short":"dispersion","clue":"Weak attractions from fleeting, temporary dipoles; the only pull between nonpolar molecules."},
{"id":"c10-double-bond","chapter":10,"section":"10.1","term":"double bond","short":"double bond","clue":"Two shared electron pairs connecting the same two atoms, as in O=O or C=O."},
{"id":"c10-electronegativity","chapter":10,"section":"10.4","term":"electronegativity","short":"electroneg.","clue":"An atom's pull on the electrons it shares in a bond; fluorine ranks highest."},
{"id":"c10-evaporation","chapter":10,"section":"10.7","term":"evaporation","short":"evaporation","clue":"Fast-moving molecules escaping from a liquid's surface into the gas phase, even below boiling."},
{"id":"c10-freezing","chapter":10,"section":"10.7","term":"freezing","short":"freezing","clue":"Liquid becoming solid as heat is removed, like water turning to ice."},
{"id":"c10-freezing-point","chapter":10,"section":"10.7","term":"freezing point (fp)","short":"freezing point","clue":"The temperature where a liquid turns solid as it is cooled; 0 °C for water."},
{"id":"c10-heat-of-fusion","chapter":10,"section":"10.7","term":"heat of fusion","short":"heat of fusion","clue":"Energy needed per gram to turn a solid into liquid with no temperature change; 334 J/g for ice."},
{"id":"c10-heat-of-vaporization","chapter":10,"section":"10.7","term":"heat of vaporization","short":"heat of vapor.","clue":"Energy needed per gram to turn a liquid into gas at its boiling point; 2260 J/g for water."},
{"id":"c10-heating-curve","chapter":10,"section":"10.7","term":"heating curve","short":"heating curve","clue":"Graph of temperature as energy is added, with slopes for warming and flat steps for phase changes."},
{"id":"c10-hydrogen-bond","chapter":10,"section":"10.6","term":"hydrogen bond","short":"hydrogen bond","clue":"Strong pull between an H attached to N, O, or F and a lone pair on another N, O, or F."},
{"id":"c10-lewis-structure","chapter":10,"section":"10.1","term":"Lewis structure","short":"Lewis structure","clue":"Dot-and-line drawing of a molecule showing bonds and lone pairs so atoms reach octets (H gets 2)."},
{"id":"c10-lewis-symbol","chapter":10,"section":"10.1","term":"Lewis symbol","short":"Lewis symbol","clue":"An element's letter(s) ringed by dots for its valence electrons, e.g., N with five dots."},
{"id":"c10-linear","chapter":10,"section":"10.3","term":"linear","short":"linear","clue":"Shape with a 180° bond angle: two groups on the central atom and no lone pairs, as in CO₂."},
{"id":"c10-melting","chapter":10,"section":"10.6","term":"melting","short":"melting","clue":"Solid turning to liquid as it absorbs heat, like ice becoming water."},
{"id":"c10-melting-point","chapter":10,"section":"10.6","term":"melting point (mp)","short":"melting point","clue":"The temperature where a solid turns liquid as it is warmed; 0 °C for ice."},
{"id":"c10-nonpolar-bond","chapter":10,"section":"10.4","term":"nonpolar covalent bond","short":"nonpolar bond","clue":"Bond where two atoms share electrons evenly, as in H–H or Cl–Cl."},
{"id":"c10-nonpolar-molecule","chapter":10,"section":"10.5","term":"nonpolar molecule","short":"nonpolar molec.","clue":"Molecule with no net charge separation: even sharing, or bond dipoles that cancel, as in CO₂."},
{"id":"c10-polar-bond","chapter":10,"section":"10.4","term":"polar covalent bond","short":"polar bond","clue":"Bond with uneven electron sharing, leaving one atom δ− and the other δ+, as in H–Cl."},
{"id":"c10-polar-molecule","chapter":10,"section":"10.5","term":"polar molecule","short":"polar molecule","clue":"Molecule with a lopsided charge, one slightly + side and one slightly − side, like H₂O."},
{"id":"c10-polarity","chapter":10,"section":"10.4","term":"polarity","short":"polarity","clue":"How uneven electron sharing is in a bond, judged by the electronegativity difference."},
{"id":"c10-resonance","chapter":10,"section":"10.2","term":"resonance structures","short":"resonance","clue":"Two or more valid Lewis drawings of one species that differ only in where a multiple bond sits."},
{"id":"c10-sublimation","chapter":10,"section":"10.7","term":"sublimation","short":"sublimation","clue":"Solid turning straight into gas, skipping the liquid stage, like dry ice."},
{"id":"c10-tetrahedral","chapter":10,"section":"10.3","term":"tetrahedral","short":"tetrahedral","clue":"3D shape with four bonded atoms and no lone pairs around the center, 109.5° apart, like CH₄."},
{"id":"c10-trigonal-planar","chapter":10,"section":"10.3","term":"trigonal planar","short":"trigonal planar","clue":"Flat shape with three bonded atoms 120° apart and no lone pairs on the center, like BF₃."},
{"id":"c10-trigonal-pyramidal","chapter":10,"section":"10.3","term":"trigonal pyramidal","short":"trig. pyramidal","clue":"Three bonded atoms plus one lone pair on the central atom, about 107° apart, as in NH₃."},
{"id":"c10-triple-bond","chapter":10,"section":"10.1","term":"triple bond","short":"triple bond","clue":"Three shared electron pairs joining the same two atoms, as in N≡N."},
{"id":"c10-vsepr","chapter":10,"section":"10.3","term":"VSEPR theory","short":"VSEPR","clue":"Shape-predicting model: electron groups around a central atom spread out to stay as far from each other as they can."},
{"id":"c11-atm","chapter":11,"section":"11.1","term":"atmosphere (atm)","short":"atm","clue":"Pressure unit equal to 760 mmHg, roughly the push of air on you at sea level."},
{"id":"c11-atmospheric-pressure","chapter":11,"section":"11.1","term":"atmospheric pressure","short":"atm. pressure","clue":"The push of Earth's blanket of air on everything beneath it; it drops as you climb a mountain."},
{"id":"c11-avogadros-law","chapter":11,"section":"11.5","term":"Avogadro’s law","short":"Avogadro’s law","clue":"At fixed P and T, doubling the moles of gas doubles its volume: V/n stays constant."},
{"id":"c11-boyles-law","chapter":11,"section":"11.2","term":"Boyle’s law","short":"Boyle’s law","clue":"At fixed T and amount, squeezing a gas to half its volume doubles its pressure: P₁V₁ = P₂V₂."},
{"id":"c11-charles-law","chapter":11,"section":"11.3","term":"Charles’s law","short":"Charles’s law","clue":"At fixed P and amount, a gas expands as its kelvin temperature rises: V/T stays constant."},
{"id":"c11-combined-gas-law","chapter":11,"section":"11.5","term":"combined gas law","short":"combined gas law","clue":"P₁V₁/T₁ = P₂V₂/T₂: links pressure, volume, and kelvin temperature for a fixed amount of gas."},
{"id":"c11-daltons-law","chapter":11,"section":"11.9","term":"Dalton’s law","short":"Dalton’s law","clue":"P(total) = P₁ + P₂ + P₃…: each gas in a mixture adds its own share to the overall pressure."},
{"id":"c11-direct-relationship","chapter":11,"section":"11.3","term":"direct relationship","short":"direct rel.","clue":"Two quantities that rise together and fall together, like gas volume and kelvin temperature."},
{"id":"c11-gay-lussacs-law","chapter":11,"section":"11.4","term":"Gay-Lussac’s law","short":"Gay-Lussac’s law","clue":"In a rigid sealed container, heating a gas raises its pressure: P/T stays constant."},
{"id":"c11-ideal-gas-constant","chapter":11,"section":"11.7","term":"ideal gas constant (R)","short":"R","clue":"0.0821 L·atm/(mol·K), or 8.314 J/(mol·K): the universal value that ties together a gas's P, V, T, and moles."},
{"id":"c11-ideal-gas-law","chapter":11,"section":"11.7","term":"ideal gas law","short":"ideal gas law","clue":"PV = nRT: one equation relating the pressure, volume, moles, and temperature of a gas."},
{"id":"c11-inverse-relationship","chapter":11,"section":"11.2","term":"inverse relationship","short":"inverse rel.","clue":"As one quantity goes up, the other goes down, like gas pressure versus volume."},
{"id":"c11-kinetic-molecular-theory","chapter":11,"section":"11.1","term":"kinetic molecular theory","short":"kinetic theory","clue":"Model picturing gases as tiny, fast, randomly moving particles that bounce off each other elastically."},
{"id":"c11-molar-volume","chapter":11,"section":"11.6","term":"molar volume","short":"molar volume","clue":"The 22.4 L that one mole of any ideal gas takes up at 0 °C and 1 atm."},
{"id":"c11-partial-pressure","chapter":11,"section":"11.9","term":"partial pressure","short":"partial pressure","clue":"The share of a gas mixture's total pressure contributed by just one of its component gases."},
{"id":"c11-pressure","chapter":11,"section":"11.1","term":"pressure","short":"pressure","clue":"Force per unit area; in a gas it comes from countless particles striking the container walls."},
{"id":"c11-stp","chapter":11,"section":"11.6","term":"STP","short":"STP","clue":"Reference set of gas conditions, 273 K and 1 atm, used so gas samples can be compared fairly."},
{"id":"c11-vapor-pressure","chapter":11,"section":"11.4","term":"vapor pressure","short":"vapor pressure","clue":"Push from molecules that escape a liquid into the space above it; it climbs as temperature rises."},
{"id":"c12-colloid","chapter":12,"section":"12.7","term":"colloid","short":"colloid","clue":"Mixture of mid-sized particles that never settle; a filter lets them by, a membrane blocks them. Ex: milk."},
{"id":"c12-concentration","chapter":12,"section":"12.4","term":"concentration","short":"concentration","clue":"How much solute is present in a given quantity of solution, e.g., in mol/L or g per 100 mL."},
{"id":"c12-dialysis","chapter":12,"section":"12.8","term":"dialysis","short":"dialysis","clue":"Membrane separation where solvent and small particles cross but large ones stay back; kidneys rely on it."},
{"id":"c12-dilution","chapter":12,"section":"12.5","term":"dilution","short":"dilution","clue":"Adding more solvent so a solution's volume grows and its strength drops; M₁V₁ = M₂V₂."},
{"id":"c12-electrolyte","chapter":12,"section":"12.2","term":"electrolyte","short":"electrolyte","clue":"Substance that breaks into ions in water, letting the solution carry an electric current."},
{"id":"c12-henrys-law","chapter":12,"section":"12.3","term":"Henry’s law","short":"Henry’s law","clue":"More gas pressure above a liquid means more of that gas dissolves, which is why soda fizzes when opened."},
{"id":"c12-hydration","chapter":12,"section":"12.1","term":"hydration","short":"hydration","clue":"Water molecules clustering around each dissolved ion, aiming their partial charges toward it."},
{"id":"c12-mass-percent","chapter":12,"section":"12.4","term":"mass percent (m/m)","short":"mass % (m/m)","clue":"Concentration found by dividing solute mass by solution mass, then multiplying by 100."},
{"id":"c12-mass-volume-percent","chapter":12,"section":"12.4","term":"mass/volume percent (m/v)","short":"m/v %","clue":"Concentration found by dividing grams of solute by milliliters of solution, then multiplying by 100."},
{"id":"c12-molality","chapter":12,"section":"12.7","term":"molality (m)","short":"molality","clue":"Moles of solute per kilogram of solvent (not of solution); it doesn't change with temperature."},
{"id":"c12-molarity","chapter":12,"section":"12.4","term":"molarity (M)","short":"molarity","clue":"Moles of solute divided by liters of the whole solution; unit is mol/L."},
{"id":"c12-nonelectrolyte","chapter":12,"section":"12.2","term":"nonelectrolyte","short":"nonelectrolyte","clue":"Substance that dissolves as intact molecules, so its solution won't conduct current; ex: sugar."},
{"id":"c12-osmosis","chapter":12,"section":"12.8","term":"osmosis","short":"osmosis","clue":"Net movement of water across a semipermeable membrane toward the side with more dissolved solute."},
{"id":"c12-osmotic-pressure","chapter":12,"section":"12.8","term":"osmotic pressure","short":"osmotic pressure","clue":"Pressure you must apply to the stronger solution to stop water from seeping into it across a membrane."},
{"id":"c12-saturated-solution","chapter":12,"section":"12.3","term":"saturated solution","short":"saturated","clue":"Holds all the solute it can at this temperature; any extra crystals just sit at the bottom."},
{"id":"c12-solubility","chapter":12,"section":"12.3","term":"solubility","short":"solubility","clue":"Upper limit of how much solute a set amount of solvent (often 100 g of water) will take up at one temperature."},
{"id":"c12-solubility-rules","chapter":12,"section":"12.3","term":"solubility rules","short":"solubility rules","clue":"Guidelines that predict whether an ionic compound will dissolve in water, e.g., all nitrates do."},
{"id":"c12-solute","chapter":12,"section":"12.1","term":"solute","short":"solute","clue":"The minor ingredient that gets dissolved in a mixture, like salt in seawater or CO₂ in soda."},
{"id":"c12-solution","chapter":12,"section":"12.1","term":"solution","short":"solution","clue":"Homogeneous mixture whose particles are ions or small molecules, too tiny to settle or be filtered out."},
{"id":"c12-solvent","chapter":12,"section":"12.1","term":"solvent","short":"solvent","clue":"The dissolving medium, usually the larger component; water plays this role in seawater."},
{"id":"c12-strong-electrolyte","chapter":12,"section":"12.2","term":"strong electrolyte","short":"strong electrol.","clue":"Compound that splits fully into ions in water, so its solution conducts current well; ex: NaCl."},
{"id":"c12-suspension","chapter":12,"section":"12.7","term":"suspension","short":"suspension","clue":"Mixture with big particles that settle on standing and get caught by a filter; ex: muddy water."},
{"id":"c12-unsaturated-solution","chapter":12,"section":"12.3","term":"unsaturated solution","short":"unsaturated","clue":"A solution that could still dissolve more solute at its current temperature."},
{"id":"c12-volume-percent","chapter":12,"section":"12.4","term":"volume percent (v/v)","short":"v/v %","clue":"Milliliters of solute over milliliters of solution, times 100; used for alcohol content in drinks."},
{"id":"c12-weak-electrolyte","chapter":12,"section":"12.2","term":"weak electrolyte","short":"weak electrolyte","clue":"Dissolves mostly as molecules with only a few ions, so its solution conducts poorly; ex: acetic acid."},
{"id":"c14-acid","chapter":14,"section":"14.1","term":"acid","short":"acid","clue":"Proton (H⁺) donor; in water it raises [H₃O⁺], tastes sour, and turns blue litmus red."},
{"id":"c14-ka","chapter":14,"section":"14.4","term":"acid dissociation constant (Kₐ)","short":"Kₐ","clue":"Equilibrium ratio [H₃O⁺][A⁻]/[HA]; the larger this value, the stronger the weak acid."},
{"id":"c14-amphoteric","chapter":14,"section":"14.2","term":"amphoteric","short":"amphoteric","clue":"Describes a species, like water or HCO₃⁻, that can either donate or accept H⁺."},
{"id":"c14-base","chapter":14,"section":"14.1","term":"base","short":"base","clue":"Proton (H⁺) acceptor; in water it raises [OH⁻], tastes bitter, and feels slippery."},
{"id":"c14-kb","chapter":14,"section":"14.4","term":"base dissociation constant (Kb)","short":"Kb","clue":"Equilibrium ratio [BH⁺][OH⁻]/[B]; a bigger value means a weak base makes more OH⁻."},
{"id":"c14-bronsted-lowry","chapter":14,"section":"14.2","term":"Brønsted–Lowry acids/bases","short":"Brønsted–Lowry","clue":"Model defining acids by H⁺ donation and bases by H⁺ acceptance, with no need for water."},
{"id":"c14-buffer","chapter":14,"section":"14.9","term":"buffer solution","short":"buffer solution","clue":"Pairing like acetic acid with acetate that soaks up added H⁺ or OH⁻ so the pH barely shifts."},
{"id":"c14-conjugate-pair","chapter":14,"section":"14.2","term":"conjugate acid–base pair","short":"conjugate pair","clue":"Two species that differ by just one H⁺, such as NH₄⁺ and NH₃."},
{"id":"c14-dissociation","chapter":14,"section":"14.3","term":"dissociation","short":"dissociation","clue":"When a dissolved compound breaks up into separate ions, e.g., HCl → H⁺ + Cl⁻ in water."},
{"id":"c14-endpoint","chapter":14,"section":"14.8","term":"endpoint","short":"endpoint","clue":"Moment in a titration when the indicator visibly changes color, signaling you to stop adding titrant."},
{"id":"c14-hydronium","chapter":14,"section":"14.2","term":"hydronium ion (H₃O⁺)","short":"H₃O⁺","clue":"A water molecule that has picked up an extra H⁺; its concentration sets a solution's pH."},
{"id":"c14-indicator","chapter":14,"section":"14.8","term":"indicator","short":"indicator","clue":"Dye that shifts color over a certain pH range, e.g., phenolphthalein turning pink in base."},
{"id":"c14-neutral","chapter":14,"section":"14.1","term":"neutral","short":"neutral","clue":"Describes a solution in which [H₃O⁺] matches [OH⁻] exactly; that means pH 7 at 25 °C."},
{"id":"c14-neutralization","chapter":14,"section":"14.1","term":"neutralization","short":"neutralization","clue":"Reaction of an acid with a base producing a salt plus H₂O, as in HCl + NaOH → NaCl + H₂O."},
{"id":"c14-ph","chapter":14,"section":"14.1","term":"pH","short":"pH","clue":"Negative log of [H₃O⁺]; values below 7 are acidic, above 7 basic, and 7 is the midpoint."},
{"id":"c14-poh","chapter":14,"section":"14.6","term":"pOH","short":"pOH","clue":"Negative log of [OH⁻]; at 25 °C it and pH always add up to 14."},
{"id":"c14-salt","chapter":14,"section":"14.7","term":"salt","short":"salt","clue":"Ionic product of an acid–base reaction: a cation other than H⁺ with an anion other than OH⁻; ex: KBr."},
{"id":"c14-strong-acid","chapter":14,"section":"14.3","term":"strong acid","short":"strong acid","clue":"Gives up every H⁺ to water, ionizing 100%; examples include HCl and HNO₃."},
{"id":"c14-strong-base","chapter":14,"section":"14.3","term":"strong base","short":"strong base","clue":"Fully breaks apart into metal cations and OH⁻ in water; examples include NaOH and KOH."},
{"id":"c14-titration","chapter":14,"section":"14.8","term":"titration","short":"titration","clue":"Lab method: add a solution of known strength bit by bit to a sample until reaction is complete, to find its concentration."},
{"id":"c14-kw","chapter":14,"section":"14.5","term":"water dissociation constant (Kw)","short":"Kw","clue":"Fixed value, 1.0 × 10⁻¹⁴ at 25 °C, that [H₃O⁺] times [OH⁻] always equals in water."},
{"id":"c14-kw-expression","chapter":14,"section":"14.5","term":"water dissociation expression","short":"Kw expression","clue":"The equation Kw = [H₃O⁺][OH⁻], used to get one ion's concentration from the other's."},
{"id":"c14-weak-acid","chapter":14,"section":"14.3","term":"weak acid","short":"weak acid","clue":"Only a small fraction of its molecules hand H⁺ to water; examples include acetic acid and HF."},
{"id":"c14-weak-base","chapter":14,"section":"14.3","term":"weak base","short":"weak base","clue":"Takes H⁺ from water only slightly, making few OH⁻ ions; example: NH₃ (ammonia)."}];
window.SKIP_SECTIONS = [];
window.CHAPTER_NAMES = {"1":"Chemistry in Our Lives","2":"Chemistry and Measurements","3":"Matter and Energy","4":"Atoms and Elements","5":"Electronic Structure of Atoms and Periodic Trends","6":"Ionic and Molecular Compounds","7":"Chemical Quantities","8":"Chemical Reactions","9":"Chemical Quantities in Reactions","10":"Bonding and Properties of Solids and Liquids","11":"Gases","12":"Solutions","14":"Acids and Bases"};
